import { test, expect } from '@playwright/test';

test.describe('Registration Form Email Validation', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/register');
  });

  test('should display error message when submitting form with invalid email', async ({ page }) => {
    // Setup: Fill in valid form fields
    const nameInput = page.getByLabel('Full Name');
    await nameInput.fill('John Doe');

    const emailInput = page.getByLabel('Email Address');
    await emailInput.fill('john.doe@example.com');

    const passwordInput = page.getByLabel('Password');
    await passwordInput.fill('SecurePassword123');

    const confirmPasswordInput = page.getByLabel('Confirm Password');
    await confirmPasswordInput.fill('SecurePassword123');

    // Intercept the form submission API
    await page.route('**/api/register', (route) => {
      route.abort('Validation failed');
    });

    // Submit the form
    const submitButton = page.getByRole('button', { name: /submit/i });
    await submitButton.click();

    // Verify error message appears
    const errorMessage = page.getByText('Please enter a valid email address');
    await expect(errorMessage).toBeVisible();

    // Verify form is still visible
    const form = page.locator('[data-testid="registration-form"]');
    await expect(form).toBeVisible();

    // Verify error message is displayed
    const errorList = page.getByText('Invalid email address');
    await expect(errorList).toBeVisible();
  });

  test('should not display error message when submitting form with valid email', async ({ page }) => {
    // Setup: Fill in valid form fields
    const nameInput = page.getByLabel('Full Name');
    await nameInput.fill('Jane Smith');

    const emailInput = page.getByLabel('Email Address');
    await emailInput.fill('jane.smith@example.com');

    const passwordInput = page.getByLabel('Password');
    await passwordInput.fill('SecurePassword123');

    const confirmPasswordInput = page.getByLabel('Confirm Password');
    await confirmPasswordInput.fill('SecurePassword123');

    // Intercept the form submission API
    await page.route('**/api/register', (route) => {
      route.continue();
    });

    // Submit the form
    const submitButton = page.getByRole('button', { name: /submit/i });
    await submitButton.click();

    // Verify success message appears
    const successMessage = page.getByText('Registration successful');
    await expect(successMessage).toBeVisible();

    // Verify form is no longer visible
    const form = page.locator('[data-testid="registration-form"]');
    await expect(form).not.toBeVisible();

    // Verify error message is not displayed
    const errorMessage = page.getByText('Please enter a valid email address');
    await expect(errorMessage).not.toBeVisible();
  });
});
